class Solution {
public:
    int minimumDeleteSum(string s1, string s2) {
        int n = s1.size();
        int m = s2.size();

        // suffix sums of ASCII values for quick base‑case lookup
        vector<int> suf1(n + 1, 0), suf2(m + 1, 0);
        for (int i = n - 1; i >= 0; --i) suf1[i] = suf1[i + 1] + (int)s1[i];
        for (int j = m - 1; j >= 0; --j) suf2[j] = suf2[j + 1] + (int)s2[j];

        // dp[i][j] = min delete sum to make s1[i:] and s2[j:] equal
        vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));

        // base cases: one string is empty
        for (int j = 0; j <= m; ++j) dp[n][j] = suf2[j];
        for (int i = 0; i <= n; ++i) dp[i][m] = suf1[i];

        // fill table bottom‑up
        for (int i = n - 1; i >= 0; --i) {
            for (int j = m - 1; j >= 0; --j) {
                if (s1[i] == s2[j]) {
                    dp[i][j] = dp[i + 1][j + 1];
                } else {
                    int delFromS1 = dp[i + 1][j] + (int)s1[i];
                    int delFromS2 = dp[i][j + 1] + (int)s2[j];
                    dp[i][j] = min(delFromS1, delFromS2);
                }
            }
        }
        return dp[0][0];
    }
};

