class Solution {
    public int minimumDeleteSum(String s1, String s2) {
        int n = s1.length();
        int m = s2.length();

        // suffix sums of ASCII values for quick base‑case lookup
        int[] suf1 = new int[n + 1];
        int[] suf2 = new int[m + 1];
        for (int i = n - 1; i >= 0; --i) {
            suf1[i] = suf1[i + 1] + (int) s1.charAt(i);
        }
        for (int j = m - 1; j >= 0; --j) {
            suf2[j] = suf2[j + 1] + (int) s2.charAt(j);
        }

        // dp[i][j] = min delete sum to make s1[i:] and s2[j:] equal
        int[][] dp = new int[n + 1][m + 1];

        // base cases: one string is empty
        for (int j = 0; j <= m; ++j) {
            dp[n][j] = suf2[j];
        }
        for (int i = 0; i <= n; ++i) {
            dp[i][m] = suf1[i];
        }

        // fill table bottom‑up
        for (int i = n - 1; i >= 0; --i) {
            for (int j = m - 1; j >= 0; --j) {
                if (s1.charAt(i) == s2.charAt(j)) {
                    dp[i][j] = dp[i + 1][j + 1];
                } else {
                    int delFromS1 = dp[i + 1][j] + (int) s1.charAt(i);
                    int delFromS2 = dp[i][j + 1] + (int) s2.charAt(j);
                    dp[i][j] = Math.min(delFromS1, delFromS2);
                }
            }
        }
        return dp[0][0];
    }
}

