/**
 * @param {string} s1
 * @param {string} s2
 * @return {number}
 */
var minimumDeleteSum = function(s1, s2) {
    const n = s1.length;
    const m = s2.length;

    // suffix sums of ASCII values for quick base-case lookup
    const suf1 = new Array(n + 1).fill(0);
    const suf2 = new Array(m + 1).fill(0);
    for (let i = n - 1; i >= 0; --i) suf1[i] = suf1[i + 1] + s1.charCodeAt(i);
    for (let j = m - 1; j >= 0; --j) suf2[j] = suf2[j + 1] + s2.charCodeAt(j);

    // dp[i][j] = min delete sum to make s1[i:] and s2[j:] equal
    const dp = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0));

    // base cases: one string is empty
    for (let j = 0; j <= m; ++j) dp[n][j] = suf2[j];
    for (let i = 0; i <= n; ++i) dp[i][m] = suf1[i];

    // fill table bottom-up
    for (let i = n - 1; i >= 0; --i) {
        for (let j = m - 1; j >= 0; --j) {
            if (s1[i] === s2[j]) {
                dp[i][j] = dp[i + 1][j + 1];
            } else {
                const delFromS1 = dp[i + 1][j] + s1.charCodeAt(i);
                const delFromS2 = dp[i][j + 1] + s2.charCodeAt(j);
                dp[i][j] = Math.min(delFromS1, delFromS2);
            }
        }
    }
    return dp[0][0];
};
